// ================================================================
// BUSCA CAMPANHAS + INSIGHTS POR CAMPANHA
// Usa this.helpers.httpRequest — compatível com n8n self-hosted
// ================================================================

const META_TOKEN = 'EAAU7CTYOnEwBRcirsZAzAFjAbBJ0ifBZA91HdZB9Nea3NBMMgfkV2xKy9IJZAElrCIZA7PBIwj94MFeJwL4FWR2ryuVkAIkz1PXHBUwZA1CbL2cn2iMkUZCKzc1bGLTbwrxHNIkbF1sKYIyA37sSxN7nI3Byq6LRmMeeR1tVJahLaexM9Fvnzt0F5kTjkuU';
const BASE = 'https://graph.facebook.com/v21.0';

const clientId   = $json.id;
const clientName = $json.cliente || 'Sem nome';
let   conta      = $json.conta_anuncio || '';

if (!conta) return [{ json: { status: 'sem_conta', cliente: clientName, metricas: [] } }];
if (!conta.startsWith('act_')) conta = 'act_' + conta.replace('act_', '');

// Helper GET com this.helpers.httpRequest (correto no n8n self-hosted)
async function apiGet(url, qs = {}) {
  return await this.helpers.httpRequest({
    method: 'GET',
    url,
    qs,
    returnFullResponse: false,
    ignoreHttpStatusErrors: false
  });
}

// Para URLs de paginação (já contém todos os query params)
async function apiGetUrl(fullUrl) {
  const u = new URL(fullUrl);
  const qs = {};
  u.searchParams.forEach((v, k) => { qs[k] = v; });
  return await apiGet(u.origin + u.pathname, qs);
}

function processActions(actions) {
  if (!actions || !actions.length) return { valor: 0, nome: null };
  const m = {};
  for (const a of actions) m[a.action_type] = parseFloat(a.value || 0);

  for (const k of ['lead','leads','onsite_conversion.lead_grouped','offsite_conversion.fb_pixel_lead','submit_application'])
    if (m[k] > 0) return { valor: m[k], nome: k };

  for (const k of ['onsite_conversion.messaging_conversation_started_7d','onsite_conversion.messaging_conversation_started_1d','omnichannel_messaging_conversation_started_7d','omnichannel_messaging_conversation_started','onsite_conversion.messaging_first_reply'])
    if (m[k] > 0) return { valor: m[k], nome: k };

  for (const k of ['contact','schedule'])
    if (m[k] > 0) return { valor: m[k], nome: k };

  if (m['purchase'] > 0) return { valor: m['purchase'], nome: 'purchase' };
  return { valor: 0, nome: null };
}

// 1. Buscar campanhas da conta
const campData = await apiGet(`${BASE}/${conta}/campaigns`, {
  access_token: META_TOKEN,
  fields: 'id,name,status,objective',
  limit: '100'
});

const campaigns = campData.data || [];
if (!campaigns.length) {
  return [{ json: { status: 'sem_campanhas', cliente: clientName, metricas: [] } }];
}

// 2. Para cada campanha, buscar insights individualmente
const metricas = [];

for (const camp of campaigns) {
  let insData;
  try {
    insData = await apiGet(`${BASE}/${camp.id}/insights`, {
      access_token: META_TOKEN,
      fields: 'date_start,spend,impressions,reach,clicks,actions',
      time_increment: '1',
      date_preset: 'last_30d',
      limit: '100'
    });
  } catch(e) { continue; }

  const rows = insData.data || [];

  // Paginação
  let nextUrl = insData.paging?.next;
  while (nextUrl) {
    try {
      const page = await apiGetUrl(nextUrl);
      rows.push(...(page.data || []));
      nextUrl = page.paging?.next;
    } catch(e) { break; }
  }

  for (const row of rows) {
    if (!row.date_start) continue;
    const res = processActions(row.actions || []);
    metricas.push({
      client_id:       clientId,
      campaign_id:     camp.id,
      campaign_name:   camp.name || 'Sem nome',
      data_referencia: row.date_start,
      investimento:    parseFloat(row.spend        || 0),
      impressoes:      parseInt(row.impressions    || 0),
      cliques_link:    parseInt(row.clicks         || 0),
      alcance:         parseInt(row.reach          || 0),
      resultado_valor: res.valor,
      resultado_nome:  res.nome
    });
  }
}

return [{ json: { status: 'ok', cliente: clientName, cliente_id: clientId, conta_anuncio: conta, total_metricas: metricas.length, metricas } }];

// Cliente sem métricas — apenas loga e continua
const c = $json.cliente || 'N/A';
const s = $json.status || 'sem_dados';
return [{ json: { status: s, cliente: c } }];
